insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('8312701c-30f3-5c12-8d27-1c27452ae515', 'rg5-context-clues-p08', (select id from public.skills where slug = 'read-g5-context-clues'), null,
        '3-5', $q$Snow Day on Maple Court$q$, $q$The storm began on Friday night. By Saturday morning, the snow on Maple Court was almost up to Ravi's knees. The whole street was silent. No cars moved, and even the birds were quiet.

Ravi looked out the window and saw Mrs. Delgado's driveway. Mrs. Delgado was elderly, nearly ninety years old, and she walked with a cane. There was no way she could shovel all that snow by herself.

Ravi pulled on his boots and grabbed a shovel. Soon his friend Lena came outside to help. Then her father joined them, and then the twins from the corner house. Working together, they made the job manageable. A chore that would have taken one person all day was finished before lunch.

Mrs. Delgado opened her door and beamed at them. Her smile was so wide that Ravi could not help grinning back. She invited everyone in for warm cocoa.

As they sat by her kitchen window, Lena said, "We should do this every time it snows." Everyone agreed. It had become a neighborhood tradition, one that started that very morning.$q$, 'draft')
